/** Starts the server on stdio. With no usable base URL it reports one line on stderr and exits 1. */
export async function main(): Promise<void> {
  const resolved = resolveBaseUrl();
  if ("problem" in resolved) {
    const message = `${resolved.problem}\n`;
    process.stderr.write(message, () => process.exit(1));
    return;
  }
  const { baseUrl } = resolved;
  const server = new Server(
    { name: SERVER_NAME, version: SERVER_VERSION },
    { capabilities: { tools: {} } },
  );

  server.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: tools.map(({ name, description, inputSchema }) => ({ name, description, inputSchema })),
  }));

  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const tool = tools.find((candidate) => candidate.name === request.params.name);
    if (!tool) {
      throw new Error(`unknown tool: ${request.params.name}`);
    }
    try {
      const result = await callApi(baseUrl, tool, (request.params.arguments ?? {}) as Args);
      return { content: [{ type: "text" as const, text: result.text }], isError: result.isError };
    } catch (error) {
      return { content: [{ type: "text" as const, text: String(error) }], isError: true };
    }
  });

  await server.connect(new StdioServerTransport());
}

